// Load from local lib in development
import { canonify } from '../../dist/index.mjs'

// Load from npm specifier
// import { canonify } from 'npm:@truestamp/canonify'

const example = {
  big: BigInt(42).toString(),
  f: false,
  fun: () => {
    console.log('hello')
  },
  n: null,
  num: 42,
  s: 'string',
  sym: Symbol('hello'),
  t: true,
  u: undefined,
  a: [
    undefined,
    null,
    true,
    false,
    'foo',
    42,
    BigInt(42).toString(),
    Symbol('hello'),
    () => {
      console.log('hello')
    },
  ],
}

console.log(canonify(example))
